<?php
declare(strict_types=1);
require_once dirname(__DIR__) . '/classes/GreenPortalDatabase.php';
require_once dirname(__DIR__) . '/classes/IdiomaService.php';
require_once dirname(__DIR__) . '/classes/UsuarioSessao.php';
require_once dirname(__DIR__) . '/classes/PermissaoTransacao.php';
require_once dirname(__DIR__) . '/classes/TransactionSecurity.php';
if (session_status() !== PHP_SESSION_ACTIVE) session_start();
if (empty($_SESSION['autenticado']) || empty($_SESSION['tenant']['banco_dados'])) { http_response_code(401); exit(IdiomaService::t('responsabilidades.erro.sessao', ['pt' => 'Sessão expirada.', 'en' => 'Your session has expired.', 'es' => 'Su sesión expiró.'])); }
$env = GreenPortalDatabase::env();
$pdo = TransactionSecurity::connect('LPRO_INFRAESTRUTURA');
if (!UsuarioSessao::atualizar($pdo, $_SESSION)) { http_response_code(401); exit(IdiomaService::t('responsabilidades.erro.sessao', ['pt' => 'Sessão expirada.', 'en' => 'Your session has expired.', 'es' => 'Su sesión expiró.'])); }
$permission = PermissaoTransacao::obter('LPRO_INFRAESTRUTURA');
if (!$permission['pode_visualizar']) { http_response_code(403); exit(IdiomaService::t('responsabilidades.erro.sem_permissao', ['pt' => 'Sem permissão para consultar responsabilidades.', 'en' => 'Not allowed to view responsibilities.', 'es' => 'Sin permiso para consultar responsabilidades.'])); }
$id = filter_input(INPUT_GET, 'CODINFRAESTRUTURA', FILTER_VALIDATE_INT, ['options' => ['min_range' => 1]]);
if (!$id) { http_response_code(400); exit(IdiomaService::t('responsabilidades.erro.infraestrutura_invalida', ['pt' => 'Infraestrutura inválida.', 'en' => 'Invalid infrastructure.', 'es' => 'Infraestructura inválida.'])); }
$json = static fn(array $value): string => json_encode($value, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
$e = static fn(mixed $value): string => htmlspecialchars((string)$value, ENT_QUOTES, 'UTF-8');
$rows = GreenPortalDatabase::call($pdo, 'CALL sp_crud_select(:tabela,:filtros,NULL,1000,0)', ['tabela' => 'vw_responsabilidade_infraestruturas', 'filtros' => $json(['CODINFRAESTRUTURA' => $id])]);
$context = GreenPortalDatabase::call($pdo, 'CALL sp_crud_select(:tabela,:filtros,NULL,1,0)', ['tabela' => 'infraestrutura', 'filtros' => $json(['CODINFRAESTRUTURA' => $id])])[0] ?? [];
?><!doctype html><html lang="<?= IdiomaService::idioma() === 'pt' ? 'pt-BR' : IdiomaService::idioma() ?>"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title><?= htmlspecialchars(IdiomaService::t('responsabilidades.titulo_infraestrutura', ['pt' => 'Responsabilidades da infraestrutura', 'en' => 'Infrastructure responsibilities', 'es' => 'Responsabilidades de la infraestructura']), ENT_QUOTES, 'UTF-8') ?></title><link rel="stylesheet" href="../assets/vendor/bootstrap/css/bootstrap.min.css?v=2"><link rel="stylesheet" href="../assets/vendor/bootstrap-icons/bootstrap-icons.css?v=2"><link rel="stylesheet" href="../assets/css/app.css?v=1"><?php require_once dirname(__DIR__) . '/components/pagina_padrao.php'; greenPortalEstiloPagina(); ?></head><body class="p-3 bg-light"><main class="container-fluid"><div class="d-flex justify-content-between align-items-start gap-3 mb-3"><div><h4 class="mb-1"><i class="bi bi-people me-2"></i><?= htmlspecialchars(IdiomaService::t('responsabilidades.titulo_infraestrutura', ['pt' => 'Responsabilidades da infraestrutura', 'en' => 'Infrastructure responsibilities', 'es' => 'Responsabilidades de la infraestructura']), ENT_QUOTES, 'UTF-8') ?></h4><div class="text-muted small"><?= htmlspecialchars(IdiomaService::t('responsabilidades.infraestrutura', ['pt' => 'Infraestrutura', 'en' => 'Infrastructure', 'es' => 'Infraestructura']), ENT_QUOTES, 'UTF-8') ?> <?= $e($id) ?> — <?= $e($context['DSCINFRAESTRUTURA'] ?? IdiomaService::t('responsabilidades.nao_localizada', ['pt' => 'Não localizada', 'en' => 'Not found', 'es' => 'No encontrada'])) ?></div></div><div class="d-flex gap-2"><a class="btn btn-sm btn-outline-primary" data-testid="toggle-manter" href="infraestrutura_responsabilidades_edicao.php?CODINFRAESTRUTURA=<?= $e($id) ?>"><i class="bi bi-pencil-square me-1"></i><?= htmlspecialchars(IdiomaService::t('responsabilidades.botao.manter', ['pt' => 'Manter', 'en' => 'Edit', 'es' => 'Mantener']), ENT_QUOTES, 'UTF-8') ?></a><span class="badge text-bg-secondary align-self-center"><?= htmlspecialchars(IdiomaService::t('responsabilidades.modo.consulta', ['pt' => 'Consulta', 'en' => 'View only', 'es' => 'Consulta']), ENT_QUOTES, 'UTF-8') ?></span></div></div><?php if (!$context): ?><div class="alert alert-warning"><?= htmlspecialchars(IdiomaService::t('responsabilidades.msg.infraestrutura_nao_localizada', ['pt' => 'A infraestrutura não foi localizada.', 'en' => 'The infrastructure was not found.', 'es' => 'La infraestructura no fue encontrada.']), ENT_QUOTES, 'UTF-8') ?></div><?php elseif (!$rows): ?><div class="alert alert-info"><?= htmlspecialchars(IdiomaService::t('responsabilidades.msg.sem_responsabilidades_infraestrutura', ['pt' => 'Não há responsabilidades cadastradas para esta infraestrutura.', 'en' => 'There are no responsibilities registered for this infrastructure.', 'es' => 'No hay responsabilidades registradas para esta infraestructura.']), ENT_QUOTES, 'UTF-8') ?></div><?php else: ?><div class="table-responsive border rounded bg-white"><table class="table table-sm table-hover align-middle mb-0"><thead class="table-light"><tr><th><?= htmlspecialchars(IdiomaService::t('responsabilidades.coluna.finalidade', ['pt' => 'Finalidade', 'en' => 'Purpose', 'es' => 'Finalidad']), ENT_QUOTES, 'UTF-8') ?></th><th><?= htmlspecialchars(IdiomaService::t('responsabilidades.coluna.responsavel', ['pt' => 'Responsável', 'en' => 'Responsible', 'es' => 'Responsable']), ENT_QUOTES, 'UTF-8') ?></th><th><?= htmlspecialchars(IdiomaService::t('responsabilidades.coluna.destino', ['pt' => 'Destino', 'en' => 'Assigned to', 'es' => 'Destino']), ENT_QUOTES, 'UTF-8') ?></th><th><?= htmlspecialchars(IdiomaService::t('responsabilidades.coluna.origem', ['pt' => 'Origem', 'en' => 'Origin', 'es' => 'Origen']), ENT_QUOTES, 'UTF-8') ?></th><th><?= htmlspecialchars(IdiomaService::t('responsabilidades.coluna.situacao', ['pt' => 'Situação', 'en' => 'Status', 'es' => 'Situación']), ENT_QUOTES, 'UTF-8') ?></th><th><?= htmlspecialchars(IdiomaService::t('responsabilidades.coluna.validade', ['pt' => 'Validade', 'en' => 'Validity', 'es' => 'Validez']), ENT_QUOTES, 'UTF-8') ?></th></tr></thead><tbody><?php foreach ($rows as $row): $active = (string)$row['SITUACAO'] === 'ATIVA'; ?><tr data-testid="responsibility-consulta-row" data-situacao="<?= $e($row['SITUACAO']) ?>"><td><?= $e($row['TIPO_NOME'] ?: IdiomaService::t('responsabilidades.responsavel_infraestrutura', ['pt' => 'Responsável pela infraestrutura', 'en' => 'Responsible for the infrastructure', 'es' => 'Responsable de la infraestructura'])) ?></td><td><?= $e($row['RESPONSAVEL_EXIBICAO']) ?></td><td><?= htmlspecialchars(IdiomaService::t('responsabilidades.destino.usuario', ['pt' => 'Usuário', 'en' => 'User', 'es' => 'Usuario']), ENT_QUOTES, 'UTF-8') ?></td><td><?= $e($row['ORIGEM']) ?></td><td><span class="badge <?= $active ? 'text-bg-success' : 'text-bg-secondary' ?>"><?= $e($row['SITUACAO']) ?></span></td><td><?= $e($row['VALIDO_DE']) ?><?= $row['VALIDO_ATE'] ? ' ' . IdiomaService::t('responsabilidades.validade.ate', ['pt' => 'a', 'en' => 'to', 'es' => 'a']) . ' ' . $e($row['VALIDO_ATE']) : ' ' . IdiomaService::t('responsabilidades.validade.em_diante', ['pt' => 'em diante', 'en' => 'onwards', 'es' => 'en adelante']) ?></td></tr><?php endforeach; ?></tbody></table></div><div class="small text-muted mt-2"><?= htmlspecialchars(IdiomaService::t('responsabilidades.msg.historico', ['pt' => 'Responsabilidades históricas são mantidas para rastreabilidade.', 'en' => 'Past responsibilities are kept for traceability.', 'es' => 'Las responsabilidades históricas se mantienen para trazabilidad.']), ENT_QUOTES, 'UTF-8') ?></div><?php endif; ?></main></body></html>
